import functools
from tenacity import retry, stop_after_attempt

def timed():
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)
        wrapper.statistics = {}
        return wrapper
    return decorator

def test_bug():
    @timed()
    @retry(stop=stop_after_attempt(3))
    def my_call():
        return "success"

    my_call()
    assert "attempt_number" in my_call.statistics
